const express = require('express');
const { Client } = require('pg');

// Mock client for testing
const mockClient = {
  _connected: false,
  _connecting: false,

  connect: async function() {
    this._connected = true;
    this._connecting = false;
  },

  query: async function(sql) {
    if (sql === 'SELECT 1 as health_check') {
      return { rows: [{ health_check: 1 }] };
    }
    throw new Error('Test query error');
  },

  end: async function() {
    this._connected = false;
  }
};

async function testHealthz() {
  console.log('Testing /healthz endpoint logic...\n');

  // Test 1: Successful health check
  console.log('Test 1: Successful database connection');
  process.env.DATABASE_URL = 'postgres://test:test@localhost:5432/test';

  let response;
  const res = {
    status: function(code) {
      this.statusCode = code;
      return this;
    },
    json: function(data) {
      this.responseData = data;
      return this;
    }
  };

  // Mock the actual client
  const originalClient = Client;
  global.Client = function() {
    return mockClient;
  };

  try {
    // Simulate successful connection
    mockClient._connected = false;

    // Import the app module to execute healthz logic
    delete require.cache[require.resolve('./app.js')];
    const app = require('./app.js');

    // Find the healthz route handler
    const routes = app._router.stack;
    let healthzHandler;

    for (const layer of routes) {
      if (layer.route && layer.route.path === '/healthz') {
        healthzHandler = layer.route.stack[0].handle;
        break;
      }
    }

    if (healthzHandler) {
      await healthzHandler({}, res);
      console.log(`Status: ${res.statusCode}`);
      console.log(`Response: ${JSON.stringify(res.responseData)}`);

      if (res.statusCode === 200 && res.responseData.db === 'ok') {
        console.log('✓ Test 1 PASSED\n');
      } else {
        console.log('✗ Test 1 FAILED\n');
      }
    }
  } catch (error) {
    console.error('Test 1 error:', error.message);
  }

  // Test 2: Database connection failure
  console.log('Test 2: Database connection failure');

  // Mock connection failure
  mockClient.connect = async function() {
    throw new Error('Connection refused');
  };

  try {
    const res2 = {
      status: function(code) {
        this.statusCode = code;
        return this;
      },
      json: function(data) {
        this.responseData = data;
        return this;
      }
    };

    mockClient._connected = false;

    delete require.cache[require.resolve('./app.js')];
    const app = require('./app.js');

    const routes = app._router.stack;
    let healthzHandler;

    for (const layer of routes) {
      if (layer.route && layer.route.path === '/healthz') {
        healthzHandler = layer.route.stack[0].handle;
        break;
      }
    }

    if (healthzHandler) {
      await healthzHandler({}, res2);
      console.log(`Status: ${res2.statusCode}`);
      console.log(`Response: ${JSON.stringify(res2.responseData)}`);

      if (res2.statusCode === 503 && res2.responseData.db === 'error') {
        console.log('✓ Test 2 PASSED\n');
      } else {
        console.log('✗ Test 2 FAILED\n');
      }
    }
  } catch (error) {
    console.error('Test 2 error:', error.message);
  }

  // Restore original Client
  global.Client = originalClient;

  console.log('Health check implementation ready for PR.');
}

testHealthz().catch(console.error);

