// Test script for health check endpoints

const http = require('http');

const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/healthz',
  method: 'GET',
  headers: {
    'Content-Type': 'application/json'
  }
};

console.log('Testing /healthz endpoint...');

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response:', data);

    if (res.statusCode === 200) {
      try {
        const response = JSON.parse(data);
        if (response.db === 'ok') {
          console.log('✓ Health check passed: Database is accessible');
        } else {
          console.log('✗ Health check failed: Invalid response format');
        }
      } catch (e) {
        console.log('✗ Health check failed: Invalid JSON response');
      }
    } else if (res.statusCode === 503) {
      console.log('✓ Health check correctly returned 503 when database is unavailable');
    } else {
      console.log(`✗ Unexpected status code: ${res.statusCode}`);
    }

    process.exit(0);
  });
});

req.on('error', (error) => {
  console.error('Request error:', error.message);
  console.log('✗ Cannot connect to server - make sure the server is running');
  process.exit(1);
