// Script to sync secrets for CI validation
const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file content into a JSON object
const secrets = {};
envContent.split('\n').forEach(line => {
  // Skip empty lines and comments
  if (!line.trim() || line.trim().startsWith('#')) {
    return;
  }

  // Parse KEY=VALUE pairs
  const match = line.match(/^\s*([^#=]+)\s*=\s*(.*)\s*$/);
  if (match) {
    const key = match[1].trim();
    const value = match[2].trim();
    // Remove quotes if present
    const cleanValue = value.replace(/^['"]|['"]$/g, '');
    secrets[key] = cleanValue;
  }
});

console.log('Parsed secrets:', Object.keys(secrets));

// POST to the CI secret-sync endpoint
const postData = JSON.stringify(secrets);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(`Secret sync status: ${res.statusCode}`);
  res.setEncoding('utf8');
  res.on('data', (chunk) => {
    console.log(`Response: ${chunk}`);
  });
  res.on('end', () => {
    console.log('Secret sync completed');
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

// Write data to request body
req.write(postData);
req.end();

