#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse .env file content into key-value pairs
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const equalsIndex = line.indexOf('=');
    if (equalsIndex !== -1) {
      const key = line.substring(0, equalsIndex).trim();
      const value = line.substring(equalsIndex + 1).trim();
      envVars[key] = value;
    }
  }
});

console.log('Read environment variables:', Object.keys(envVars).join(', '));

// Prepare request options
const postData = JSON.stringify(envVars);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

// Make the POST request
const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    if (data) {
      console.log('Response:', data);
    }
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('CI secret sync completed successfully');
      process.exit(0);
    } else {
      console.error('CI secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Request failed:', error.message);
  // If the CI secret sync endpoint is not available, we should still exit successfully
  // as this might be running in a non-CI environment
  console.log('Note: CI secret sync endpoint not available, continuing...');
  process.exit(0);
});

req.write(postData);
req.end();

