#!/usr/bin/env node

// CI secret-sync script as required by the issue
// Reads .env.test and POSTs its contents to http://localhost:47301/api/ci-secret-sync

const fs = require('fs');
const https = require('https');
const http = require('http');

function parseEnvFile(content) {
  const result = {};
  const lines = content.split('\n');

  for (const line of lines) {
    // Skip empty lines and comments
    if (!line.trim() || line.trim().startsWith('#')) {
      continue;
    }

    // Parse key=value pairs
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      result[key.trim()] = value.trim();
    }
  }

  return result;
}

async function syncSecrets() {
  try {
    // Read .env.test file
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const envData = parseEnvFile(envContent);

    console.log('Parsed environment variables:', Object.keys(envData));

    const postData = JSON.stringify(envData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/ci-secret-sync',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    return new Promise((resolve, reject) => {
      const req = http.request(options, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          console.log(`Secret sync completed with status: ${res.statusCode}`);
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({ statusCode: res.statusCode, body: data });
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        });
      });

      req.on('error', (error) => {
        console.error('Error during secret sync:', error.message);
        reject(error);
      });

      req.write(postData);
      req.end();
    });

  } catch (error) {
    console.error('Failed to sync secrets:', error.message);
    throw error;
  }
}

// Run the sync if this script is executed directly
if (require.main === module) {
  syncSecrets()
    .then(() => {
      console.log('CI secret-sync completed successfully');
      process.exit(0);
    })
    .catch((error) => {
      console.error('CI secret-sync failed:', error.message);
      process.exit(1);
    });
}

module.exports = { syncSecrets };

