pool.on('error', (err) => {
  console.error('Unexpected database pool error:', err.message);
});

// Simple database health check function
async function checkDatabaseHealth() {
  let client;
  try {
    // Try to connect to the database with a timeout
    client = await pool.connect();

    // Try to query the database with a simple select
    const result = await client.query('SELECT 1 as health_check');

    // Verify we got a result
    if (result && result.rows && result.rows[0] && result.rows[0].health_check === 1) {
      return { healthy: true, message: 'Database connection successful' };
    } else {
      return { healthy: false, message: 'Database query returned invalid result' };
