  } catch (error) {
    console.error('Database health check failed:', error.message);
    return { 
      healthy: false, 
      message: `Database connection failed: ${error.message}` 
    };
  } finally {
    // Always release the client back to the pool
    if (client) {
      client.release();
    }
  }
}

