#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file content
const secrets = {};
const lines = envContent.split('\n');

for (const line of lines) {
  // Skip comments and empty lines
  if (line.startsWith('#') || line.trim() === '') {
    continue;
  }

  const [key, ...valueParts] = line.split('=');
  if (key && valueParts.length > 0) {
    secrets[key.trim()] = valueParts.join('=').trim();
  }
}

// Convert to JSON
const secretsJson = JSON.stringify(secrets);

console.log('Sending secrets to CI secret-sync endpoint...');

// Determine protocol based on URL
const url = 'http://localhost:47301/api/ci-secret-sync';
const isHttps = url.startsWith('https://');
const client = isHttps ? https : http;

const options = {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(secretsJson)
  }
};

const req = client.request(url, options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('Successfully synced secrets with CI');
      console.log('Response:', data);
    } else {
      console.error(`Failed to sync secrets. Status: ${res.statusCode}`);
      console.error('Response:', data);
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Error syncing secrets:', error.message);
  process.exit(1);
});

req.write(secretsJson);
req.end();

